CopyOnWriteArrayList<Integer> cowList = new CopyOnWriteArrayList<>();
for (int i = 0; i < 100_000; i++) {
    cowList.add(i); // 100,000 array copies!
}

// FIX: Use synchronizedList or a concurrent queue for write-heavy scenarios
